module tb_TopModule;
    reg clk;
    reg ar;
    reg d;
    wire q;

    TopModule dut (
        .clk(clk),
        .ar(ar),
        .d(d),
        .q(q)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        // Initialize
        ar = 0;
        d = 0;
        #3;

        // Test async reset
        ar = 1;
        #2;
        if (q !== 0) begin
            $display("SELFTEST FAIL: async reset failed, q=%b", q);
            $finish;
        end

        ar = 0;
        #3;

        // Test D sampling on posedge
        d = 1;
        #7; // before posedge
        if (q !== 0) begin
            $display("SELFTEST FAIL: q changed before posedge, q=%b", q);
            $finish;
        end

        @(posedge clk);
        #1;
        if (q !== 1) begin
            $display("SELFTEST FAIL: q did not sample d=1, q=%b", q);
            $finish;
        end

        // Change d, wait for posedge
        d = 0;
        @(posedge clk);
        #1;
        if (q !== 0) begin
            $display("SELFTEST FAIL: q did not sample d=0, q=%b", q);
            $finish;
        end

        // Test async reset while clock is running
        #2;
        ar = 1;
        #1;
        if (q !== 0) begin
            $display("SELFTEST FAIL: async reset mid-cycle failed, q=%b", q);
            $finish;
        end

        ar = 0;
        d = 1;
        @(posedge clk);
        #1;
        if (q !== 1) begin
            $display("SELFTEST FAIL: recovery from async reset failed, q=%b", q);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
